import React, { useState, useEffect } from 'react';
import './AppMain.css'
import { User, Download } from 'lucide-react';
import { data, useLocation, useNavigate } from 'react-router-dom';

function AppMain() {
  const location = useLocation();
  const navigate = useNavigate();
  const username = location.state?.username || "Invitado";
  const [showMenu, setShowMenu] = useState(false);
  const [historial, setHistorial] = useState([]);

  useEffect(() => {
    fetch("http://localhost:8081/api/historial")
      .then(response => response.json())
      .then(data => setHistorial(data))
      .catch(error => console.error("Error al obtener los registros:", error));
  }, []);

  const toggleMenu = () => {
    setShowMenu(!showMenu);
  };

  const logout = () => {
    navigate("/");
  };

  return (
    <div className='Main'>
      <header className='Main-header'>
        <img src="/logoQuiros.png" />
        <div className='usuario' onClick={toggleMenu}>
          <User />
          <strong>{username}</strong></div>
          {showMenu && (
            <div className='dropdown'>
              <button onClick={logout}>Cerrar Sesion</button>
            </div>
          )}
      </header>
      <main>
          <div className='Main-menu'>
            <button>Registro Horas</button>
          </div>
          <div className='Main-body'>
              <button>Añadir registro</button>
              <button><Download></Download></button>
              <table className='table'>
                <thead>
                  <td>Usuario</td>
                  <td>Proyecto</td>
                  <td>Tarea</td>
                  <td>Horas</td>
                  <td>Descripcion</td>
                </thead>
                <tbody>
                  {historial.map((historiales) => (
                    <tr key={historiales.id}>
                      <td>{historiales.usuario}</td>
                      <td>{historiales.proyecto}</td>
                      <td>{historiales.tarea}</td>
                      <td>{historiales.horas}</td>
                      <td>{historiales.descripcion}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
          </div>
      </main>
    </div>
  );
}

export default AppMain;
